const mails = await api.get("/mails", { label: "refund" });
const refundMails = mails.items.filter(m => m.label === "refund" && m.customer_id);
const customers = await api.get("/customers", { tier: "gold" });
const goldIds = new Set(customers.items.filter(c => c.tier === "gold").map(c => c.id));
const names = [...new Set(refundMails.filter(m => goldIds.has(m.customer_id)).map(m => {
  const c = customers.items.find(c => c.id === m.customer_id);
  return c.name;
}))];
return { mailCount: mails.count, refundCount: refundMails.length, customerCount: customers.count, names };
